<!--
  Ficheiro: src/views/LiveView.vue
  Tipo: Página Vue.
  Função: Recupera a biblioteca TV e separa a consulta dos canais da construÃ§Ã£o dos filtros.
-->
<script setup lang="ts">
import { computed,onMounted,ref,watch } from "vue";import BaseEmptyState from "@/components/base/BaseEmptyState.vue";import BasePageHeader from "@/components/base/BasePageHeader.vue";import BasePagination from "@/components/base/BasePagination.vue";import ChannelCard from "@/components/live/ChannelCard.vue";import ChannelFilters from "@/components/live/ChannelFilters.vue";import GridSizeSlider from "@/components/live/GridSizeSlider.vue";import ChannelDetailDialog from "@/components/live/ChannelDetailDialog.vue";import ChannelEditDialog from "@/components/live/ChannelEditDialog.vue";import { channelRepository,countryRepository,languageRepository,streamLinkRepository,tagRepository,tvCategoryRepository } from "@/domain/repositories";import { usedCategories,usedCountries,usedQualities } from "@/domain/live/filterOptions";import type { ChannelRecord,NamedRecord,StreamLinkRecord,TvCategoryRecord } from "@/types/records";
const channels=ref<ChannelRecord[]>([]),allChannels=ref<ChannelRecord[]>([]),page=ref(1),pages=ref(1),total=ref(0),loading=ref(true),error=ref("");const search=ref(""),country=ref(""),category=ref(""),quality=ref(""),status=ref(""),favorite=ref("");const view=ref<"grid"|"logos"|"list"|"compact">("grid");const gridCardWidth=ref<number>(Math.min(420,Math.max(170,Number(localStorage.getItem("mediario-tv-grid-width"))||250)));const countries=ref<NamedRecord[]>([]),languages=ref<NamedRecord[]>([]),tags=ref<NamedRecord[]>([]),categories=ref<TvCategoryRecord[]>([]);const selected=ref<ChannelRecord|null>(null),editing=ref<ChannelRecord|null>(null),links=ref<StreamLinkRecord[]>([]),linksLoading=ref(false);let timer:ReturnType<typeof setTimeout>;
const countryOptions=computed(()=>usedCountries(allChannels.value,countries.value));const categoryOptions=computed(()=>usedCategories(allChannels.value,categories.value));const qualityOptions=computed(()=>usedQualities(allChannels.value));const filterCount=computed(()=>[search.value,country.value,category.value,quality.value,status.value,favorite.value].filter(Boolean).length);const esc=(v:string)=>v.replaceAll("\\","\\\\").replaceAll('"','\\"');function queryFilter(){const terms=["cemiterio = false"];if(search.value.trim()){const q=esc(search.value.trim());terms.push(`(nome ~ "${q}" || tvg_name ~ "${q}" || tvg_id ~ "${q}" || epg_id ~ "${q}" || playlist_origem ~ "${q}")`)}if(country.value)terms.push(`pais = "${country.value}"`);if(category.value)terms.push(`categoria = "${category.value}"`);if(quality.value)terms.push(`qualidade = "${quality.value}"`);if(status.value)terms.push(`ativo = ${status.value==="active"}`);if(favorite.value)terms.push(`favorito = ${favorite.value==="yes"}`);return terms.join(" && ")}
async function loadLibrary(){loading.value=true;error.value="";try{const result=await channelRepository.list({page:page.value,perPage:18,filter:queryFilter(),sort:"ordem,nome",expand:"pais,categoria,idiomas,tags"});channels.value=result.items;pages.value=result.totalPages||1;total.value=result.totalItems}catch(c){error.value=c instanceof Error?c.message:String(c);channels.value=[]}finally{loading.value=false}}
async function loadAllChannels(){const result:ChannelRecord[]=[];let current=1,totalPages=1;do{const response=await channelRepository.list({page:current,perPage:500,filter:"cemiterio = false",sort:"nome"});result.push(...response.items);totalPages=response.totalPages||1;current++}while(current<=totalPages);allChannels.value=result}
async function loadLookups(){const [p,c,i,t]=await Promise.all([countryRepository.list({page:1,perPage:250,filter:"ativo = true",sort:"ordem,nome"}),tvCategoryRepository.list({page:1,perPage:100,filter:"ativo = true",sort:"ordem,nome"}),languageRepository.list({page:1,perPage:100,filter:"ativo = true",sort:"ordem,nome"}),tagRepository.list({page:1,perPage:200,filter:"ativo = true",sort:"ordem,nome"})]);countries.value=p.items;categories.value=c.items;languages.value=i.items;tags.value=t.items}
async function openChannel(channel:ChannelRecord){selected.value=channel;linksLoading.value=true;try{const result=await streamLinkRepository.list({page:1,perPage:100,filter:`canal_tv = "${channel.id}"`,sort:"prioridade"});links.value=result.items}finally{linksLoading.value=false}}
function updateChannel(channel:ChannelRecord){channels.value=channels.value.map(x=>x.id===channel.id?channel:x);allChannels.value=allChannels.value.map(x=>x.id===channel.id?channel:x);if(selected.value?.id===channel.id)selected.value=channel}function saved(channel:ChannelRecord){updateChannel(channel);editing.value=null}function archived(id:string){channels.value=channels.value.filter(x=>x.id!==id);allChannels.value=allChannels.value.filter(x=>x.id!==id);if(selected.value?.id===id)selected.value=null;editing.value=null;total.value=Math.max(0,total.value-1)}function clear(){search.value=country.value=category.value=quality.value=status.value=favorite.value="";page.value=1;void loadLibrary()}
watch(gridCardWidth,value=>localStorage.setItem("mediario-tv-grid-width",String(value)));watch([search,country,category,quality,status,favorite],()=>{clearTimeout(timer);timer=setTimeout(()=>{page.value=1;void loadLibrary()},250)});watch(countryOptions,value=>{if(country.value&&!value.some(x=>x.value===country.value))country.value=""});watch(categoryOptions,value=>{if(category.value&&!value.some(x=>x.value===category.value))category.value=""});watch(qualityOptions,value=>{if(quality.value&&!value.some(x=>x.value===quality.value))quality.value=""});onMounted(async()=>{await Promise.all([loadLookups(),loadAllChannels()]);await loadLibrary()});
</script>
<template><BasePageHeader eyebrow="Televisão IP" title="IPTV" :description="`${total} canais configurados`"><template #actions><button class="button button-primary" type="button" disabled>⇩ Importar M3U, em breve</button></template></BasePageHeader><div v-if="error" class="form-alert form-alert-error" role="alert">{{error}}</div><ChannelFilters v-model:search="search" v-model:country="country" v-model:category="category" v-model:quality="quality" v-model:status="status" v-model:favorite="favorite" :countries="countryOptions" :categories="categoryOptions" :qualities="qualityOptions" :count="filterCount" @clear="clear"/><div class="section-heading"><div><p class="eyebrow">Biblioteca</p><h2>Canais IPTV</h2></div><div class="live-view-tools"><GridSizeSlider v-if="view==='grid'||view==='logos'" v-model="gridCardWidth"/><div class="view-switch" role="group" aria-label="Vista dos canais"><button type="button" :class="{'is-active':view==='grid'}" @click="view='grid'">▦ Grelha</button><button type="button" :class="{'is-active':view==='logos'}" @click="view='logos'">▦ Logos</button><button type="button" :class="{'is-active':view==='list'}" @click="view='list'">☰ Lista</button><button type="button" :class="{'is-active':view==='compact'}" @click="view='compact'">≡ Compacta</button></div></div></div><div v-if="loading" class="page-loading" aria-live="polite"><span class="loader" aria-hidden="true"/><span class="sr-only">A carregar canais IPTV.</span></div><div v-else-if="channels.length" class="live-collection" :class="`is-${view}`" :style="(view==='grid'||view==='logos')?{gridTemplateColumns:`repeat(auto-fill, minmax(min(${gridCardWidth}px, 100%), 1fr))`}:undefined"><ChannelCard v-for="item in channels" :key="item.id" :channel="item" :view="view" @open="openChannel" @edit="editing=$event"/></div><BaseEmptyState v-else icon="▣" title="Sem canais IPTV" description="Não existem canais para estes filtros."/><BasePagination :page="page" :pages="pages" label="Paginação dos canais" @change="page=$event;loadLibrary()"/><ChannelDetailDialog :channel="selected" :links="links" :loading="linksLoading" @close="selected=null" @edit="editing=$event" @links-changed="links=$event" @channel-changed="updateChannel"/><ChannelEditDialog :channel="editing" :countries="countries" :languages="languages" :tags="tags" :categories="categories" @close="editing=null" @saved="saved" @archived="archived"/></template>
<style scoped>
.live-view-tools{display:flex;align-items:center;justify-content:flex-end;gap:.75rem;flex-wrap:wrap}
@media(max-width:700px){.live-view-tools{align-items:stretch;flex-direction:column;width:100%}}
</style>




